# Copy the tracked Android sources for scheduled check-in into gen/android and
# patch the three generated files WorkManager needs.
#
# gen/ is gitignored and regenerated by `tauri android init`, so the Kotlin
# sources live in apps/desktop/android/src and are copied on every build.
# Everything here is idempotent.
#
# NOTE: keep this file pure ASCII. Windows PowerShell 5.1 reads .ps1 files with
# the system ANSI code page unless a BOM is present.
param(
    [string] $AppDir = (Join-Path $PSScriptRoot '..\apps\desktop')
)

$ErrorActionPreference = 'Stop'

$srcRoot = Join-Path $AppDir 'android\src\cn\pointhub\desktop'
$dstRoot = Join-Path $AppDir 'src-tauri\gen\android\app\src\main\java\cn\pointhub\desktop'
$manifest = Join-Path $AppDir 'src-tauri\gen\android\app\src\main\AndroidManifest.xml'
$gradle = Join-Path $AppDir 'src-tauri\gen\android\app\build.gradle.kts'
$activity = Join-Path $dstRoot 'MainActivity.kt'

foreach ($f in @($manifest, $gradle, $activity)) {
    if (-not (Test-Path $f)) {
        Write-Host "  missing generated file: $f (run tauri android init first)"
        exit 1
    }
}

$utf8 = New-Object System.Text.UTF8Encoding($false)

# --- 0. buildSrc BuildTask: point node at the project's Tauri CLI ------------
# The generated template runs `node tauri android android-studio-script` with
# cwd = src-tauri. That only works when a `tauri` package is resolvable from
# there, which it is not: the CLI lives in ui/node_modules. Patch the first
# argument to the real tauri.js path (relative to src-tauri) so `node` can load
# it without PATH or global installs.
$buildTask = Get-ChildItem (Join-Path $AppDir 'src-tauri\gen\android\buildSrc') -Recurse -Filter BuildTask.kt -ErrorAction SilentlyContinue | Select-Object -First 1
$cliJs = Join-Path $AppDir 'ui\node_modules\@tauri-apps\cli\tauri.js'
if (-not (Test-Path $cliJs)) {
    Write-Host "  WARNING: local Tauri CLI not installed: $cliJs (run npm install in apps/desktop/ui)"
} elseif ($null -eq $buildTask) {
    Write-Host '  WARNING: buildSrc BuildTask.kt not found, node CLI path left unchanged'
} else {
    $bt = [System.IO.File]::ReadAllText($buildTask.FullName)
    if ($bt -match 'node_modules/@tauri-apps/cli/tauri\.js') {
        Write-Host '  buildSrc: tauri CLI path already patched'
    } elseif ($bt -match 'listOf\("tauri", "android", "android-studio-script"\)') {
        $bt = $bt.Replace(
            'listOf("tauri", "android", "android-studio-script")',
            'listOf("../ui/node_modules/@tauri-apps/cli/tauri.js", "android", "android-studio-script")'
        )
        [System.IO.File]::WriteAllText($buildTask.FullName, $bt, $utf8)
        Write-Host '  buildSrc: node -> ui/node_modules/@tauri-apps/cli/tauri.js'
    } else {
        Write-Host '  WARNING: tauri CLI args pattern not found, BuildTask.kt left unchanged'
    }
}

# --- 1. Kotlin sources ------------------------------------------------------
New-Item -ItemType Directory -Force -Path $dstRoot | Out-Null
$copied = 0
Get-ChildItem $srcRoot -Filter *.kt | ForEach-Object {
    $dest = Join-Path $dstRoot $_.Name
    $same = (Test-Path $dest) -and ((Get-FileHash $_.FullName).Hash -eq (Get-FileHash $dest).Hash)
    if (-not $same) {
        Copy-Item $_.FullName $dest -Force
        $copied++
    }
}
Write-Host "  kotlin sources: $copied copied, $((Get-ChildItem $srcRoot -Filter *.kt).Count) tracked"

# --- 2. manifest: notification permission -----------------------------------
$text = [System.IO.File]::ReadAllText($manifest)
if ($text -notmatch 'android\.permission\.POST_NOTIFICATIONS') {
    $anchor = '<uses-permission android:name="android.permission.INTERNET" />'
    if ($text -notmatch [regex]::Escape($anchor)) {
        Write-Host '  WARNING: INTERNET permission not found, manifest left unchanged'
    } else {
        $insert = $anchor + "`n    <uses-permission android:name=`"android.permission.POST_NOTIFICATIONS`" />"
        $text = $text.Replace($anchor, $insert)
        [System.IO.File]::WriteAllText($manifest, $text, $utf8)
        Write-Host '  manifest: POST_NOTIFICATIONS added'
    }
}

# --- 2b. manifest: install packages permission ------------------------------
# Android 8+ requires this permission before the app may hand an APK to the
# system installer. The user still has to allow "install unknown apps" once.
$text = [System.IO.File]::ReadAllText($manifest)
if ($text -notmatch 'android\.permission\.REQUEST_INSTALL_PACKAGES') {
    $anchor = '<uses-permission android:name="android.permission.POST_NOTIFICATIONS" />'
    if ($text -notmatch [regex]::Escape($anchor)) {
        Write-Host '  WARNING: POST_NOTIFICATIONS anchor missing, install permission skipped'
    } else {
        $insert = $anchor + "`n    <uses-permission android:name=`"android.permission.REQUEST_INSTALL_PACKAGES`" />"
        $text = $text.Replace($anchor, $insert)
        [System.IO.File]::WriteAllText($manifest, $text, $utf8)
        Write-Host '  manifest: REQUEST_INSTALL_PACKAGES added'
    }
}

# --- 2c. res/xml/file_paths.xml: expose files/updates to the installer ------
# APKs live in getFilesDir()/updates; FileProvider only hands out paths that
# are whitelisted here. The template ships the file but without this entry.
$xmlDir = Join-Path $AppDir 'src-tauri\gen\android\app\src\main\res\xml'
$filePaths = Join-Path $xmlDir 'file_paths.xml'
if (-not (Test-Path $filePaths)) {
    New-Item -ItemType Directory -Force -Path $xmlDir | Out-Null
    $xml = "<?xml version=`"1.0`" encoding=`"utf-8`"?>`n<paths>`n    <files-path name=`"updates`" path=`"updates/`" />`n</paths>`n"
    [System.IO.File]::WriteAllText($filePaths, $xml, $utf8)
    Write-Host '  file_paths.xml: created with files/updates'
} else {
    $text = [System.IO.File]::ReadAllText($filePaths)
    if ($text -notmatch 'name="updates"') {
        if ($text -match '</paths>') {
            $text = $text.Replace('</paths>', "    <files-path name=`"updates`" path=`"updates/`" />`n</paths>")
            [System.IO.File]::WriteAllText($filePaths, $text, $utf8)
            Write-Host '  file_paths.xml: files/updates added'
        } else {
            Write-Host '  WARNING: file_paths.xml has no </paths>, left unchanged'
        }
    }
}

# --- 3. gradle: WorkManager dependency --------------------------------------
$text = [System.IO.File]::ReadAllText($gradle)
if ($text -notmatch 'androidx\.work:work-runtime-ktx') {
    if ($text -match '(?m)^dependencies\s*\{') {
        $text = [regex]::Replace(
            $text,
            '(?m)^dependencies\s*\{',
            "dependencies {`n    implementation(`"androidx.work:work-runtime-ktx:2.9.1`")"
        )
        [System.IO.File]::WriteAllText($gradle, $text, $utf8)
        Write-Host '  gradle: WorkManager dependency added'
    } else {
        Write-Host '  WARNING: dependencies block not found, gradle file left unchanged'
    }
}

# --- 3b. proguard: WorkManager keep rules -----------------------------------
# WorkManager rebuilds the Room database and its workers by class name at
# runtime; R8 otherwise strips them and the app dies on startup with
# "Failed to create an instance of class androidx.work.impl.WorkDatabase".
$pro = Join-Path $AppDir 'src-tauri\gen\android\app\proguard-pointhub.pro'
$rules = @(
    '# PointHub: generated by scripts/patch-android-sources.ps1',
    '-keep class androidx.work.** { *; }',
    '-keep class androidx.room.** { *; }',
    '-keep class * extends androidx.work.ListenableWorker { <init>(...); }',
    '-keep class cn.pointhub.desktop.CheckinBridge { *; }',
    '-keep class cn.pointhub.desktop.ApkInstaller { *; }',
    '-keepclasseswithmembernames class * { native <methods>; }',
    '-dontwarn androidx.work.**'
) -join "`n"
$rules = $rules + "`n"
if (-not (Test-Path $pro) -or [System.IO.File]::ReadAllText($pro) -ne $rules) {
    [System.IO.File]::WriteAllText($pro, $rules, $utf8)
    Write-Host '  proguard: WorkManager keep rules written'
}

# --- 4. MainActivity: schedule + notification permission --------------------
$text = [System.IO.File]::ReadAllText($activity)
if ($text -notmatch 'CheckinScheduler\.ensureScheduled') {
    $anchor = 'super.onCreate(savedInstanceState)'
    if ($text -notmatch [regex]::Escape($anchor)) {
        Write-Host '  WARNING: onCreate anchor not found, MainActivity left unchanged'
    } else {
        $insert = $anchor + "`n    CheckinScheduler.ensureScheduled(this)`n    CheckinNotify.ensurePermission(this)"
        $text = $text.Replace($anchor, $insert)
        [System.IO.File]::WriteAllText($activity, $text, $utf8)
        Write-Host '  MainActivity: daily schedule + notification permission wired'
    }
}

# --- 5. MainActivity: resume APK install after granting unknown sources -----
# The user leaves the app for the system "install unknown apps" screen; on
# return, ApkInstaller.resumePending re-opens the installer automatically.
$text = [System.IO.File]::ReadAllText($activity)
if ($text -notmatch 'ApkInstaller\.resumePending') {
    $anchor = 'CheckinNotify.ensurePermission(this)'
    if ($text -notmatch [regex]::Escape($anchor)) {
        Write-Host '  WARNING: onCreate anchor not found, ApkInstaller resume not wired'
    } else {
        $pattern = '(?s)(' + [regex]::Escape($anchor) + '\s*\r?\n\s*\})'
        $m = [regex]::Match($text, $pattern)
        if ($m.Success) {
            $tail = "override fun onResume() {`n    super.onResume()`n    ApkInstaller.resumePending(this)`n  }"
            $text = $text.Replace($m.Value, $m.Value + "`n`n  " + $tail)
            [System.IO.File]::WriteAllText($activity, $text, $utf8)
            Write-Host '  MainActivity: ApkInstaller.resumePending wired'
        } else {
            Write-Host '  WARNING: onCreate closing brace not found, ApkInstaller resume not wired'
        }
    }
}

Write-Host '  android sources patch done'
